//📑 设置源变量为关键字时转换搜索接口
//没啥用的功能，详情页地址都是一样的。
var v = String(source.getVariable())
if(v!=""&&v!=null){
if(v.match(/^[1一壹qQ]$/)){
//西红柿小说
		url="https://api.xihongshixsapp.com"
	}
else if(v.match(/^[2二贰wW]$/)){
//米趣小说
		url="https://api.miquxiaoshuoapp.com"
	}
else if(v.match(/^[3三叁eE]$/)){
//玫瑰小说
		url="https://api.meiguixsapp.com"
	}
else if(v.match(/^[4四肆rR]$/)){
//随梦小说
		url="https://api.suimengapp.com"
	}
else if(v.match(/^[5五伍tT]$/)){
//81中文
		url="https://api.81zwapp.com"
	}
else if(v.match(/^[6六陆yY]$/)){
//天籁小说
		url="https://api.tianlaixsapp.com"
	}
else if(v.match(/^[7七柒uU]$/)){
//笔趣屋
		url="https://api.ywpxg.com"
	}
else if(v.match(/^[8八捌iI]$/)){
//趣读小说
		url="https://api.quduapp.com"
	}
else if(v.match(/^[9九玖oO]$/)){
//书荒阁
		url="https://api.shgxsapp.com"
	}
else if(v.match(/^[0〇零pP]$/)){
//棉花糖小说
		url="https://api.mianhuatangxs.cn"
	}
else if(v.match(/^[11十一拾壹]{2}$/)){
//小说部落
		url="https://api.xiaoshuobuluo.cn"
	}
else if(v.match(/^[12十二拾贰]{2}$/)){
//笔趣阁
		url="https://api.diwudianqi6.cn"
	}
else if(v.match(/^[13十三拾叁]{2}$/)){
//abc小说
		url="https://api.abcxiaoshuoapp.com"
	}
else if(v.match(/^[14十四拾肆]{2}$/)){
//51小说
		url="https://api.51xiaoshuoapp.com"
}else{url="http://statics.ywpxg.com"}
}else{url="http://statics.rungean.com"}

