;[
		["男",[["玄幻","lejRej"],["武侠","nel5aK"],["都市","mbk5ez"],["仙侠","vbmOeY"],["军事","penRe7"],["历史","xbojag"],["游戏","mep2bM"],["科幻","zbq2dp"],["轻小说","YerEdO"]]],
		["女",[["现代言情","9avmeG"],["古代言情","DdwRb1"],["幻想言情","7ax9by"],["青春校园","Pdy7aQ"],["唯美纯爱","kazYeJ"],["同人衍生","9aAOdv"]]]
].map(([title,list],channel)=>{
		channel++;
		push("༺ˇ»`ʚ "+title+"生频道 ɞ´«ˇ༻",null,1);
		push("༺ˇ»`ʚ 榜单 ɞ´«ˇ༻",null,1);
		["必读榜","完本榜","更新榜","搜索榜","潜力榜","评论榜","人气完本","新书速递"].map((title,i)=>{
				i++
				if(i<7){
						i = "rank?type="+i+"&";
					}
				else{
						i = i<8?"mep2bM?":"YerEdO?";
					}
				push(title,$$(i,channel,1),0.25);
			});
		push("༺ˇ»`ʚ 分类 ɞ´«ˇ༻",null,1);
		list.map([title,B]=>{
				push("༺ "+title+" ༻",$$(1,B,0),1);
				["热度","更新","评分","新书"].map((title,A)=>{
						A++;
						["["+title+"]","连载","完结"].map((title,C)=>{
								C=C?"&isComplete="+(C-1):"";
								push(title,$$(A,B+C,0),0.25);
							});
					});
			});
	}); 
JSON.stringify(sort);

